class MySQLDatabase:
    def __init__(self):
        self.storage = {}

class UserManager:
    def __init__(self, db: MySQLDatabase):
        self.database = db

    def get_user(self, id: int) -> str:
        return self.database.storage.get(id, 'User not found')

    def add_user(self, id: int, name: str) -> None:
        if id in self.database.storage:
            print('User ID already exists.')
        else:
            self.database.storage[id] = name
            print('User added successfully.')

    def update_user(self, id: int, name: str) -> None:
        if id in self.database.storage:
            self.database.storage[id] = name
            print('User updated successfully.')
        else:
            print('User ID does not exist.')

    def delete_user(self, id: int) -> None:
        if id in self.database.storage:
            del self.database.storage[id]
            print('User deleted successfully.')
        else:
            print('User ID not found.')
